window.docContents[110].resolve({"/UD-VII___-paradigms/#Core-C______--UD-VII___-paradigms":{"contents":"The last unit adds no construction to Core C++. Three of the four paradigms are read as restrictions of the core, each a predicate over the abstract syntax, and the restriction buys a property the whole language does not have. The logic paradigm has no counterpart in the core, so it gets a language of its own, a set of Horn clauses whose meaning is given by the SLD resolution judgment, written in the same notation as the rest of the course.\n\n\n\n\n\n\n\n","context":"Core C++","header":"8. UD VII, paradigms","id":"/UD-VII___-paradigms/#Core-C______--UD-VII___-paradigms"}});